CREATE TABLE "achievements" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"slug" varchar(255) NOT NULL,
	"title_en" varchar(300) NOT NULL,
	"title_ta" varchar(300),
	"summary_en" text DEFAULT '' NOT NULL,
	"summary_ta" text,
	"content_en" text DEFAULT '' NOT NULL,
	"content_ta" text,
	"image_url" text,
	"image_alt" varchar(300),
	"icon" varchar(32) DEFAULT 'award' NOT NULL,
	"highlight" boolean DEFAULT false NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"status" varchar(16) DEFAULT 'published' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "achievements_slug_unique" UNIQUE("slug")
);
--> statement-breakpoint
CREATE INDEX "achievements_status_sort_idx" ON "achievements" USING btree ("status","sort_order");
--> statement-breakpoint
-- Starting content from the "Achievements of Hon. S. P. Velumani" document.
INSERT INTO "achievements" ("slug", "title_en", "summary_en", "content_en", "icon", "highlight", "sort_order") VALUES
('athikadavu-avinashi-water-project', 'Advancing the Athikadavu–Avinashi Water Project', 'A ₹1,652-crore scheme to recharge tanks and ponds across Coimbatore, Tiruppur and Erode, benefiting about 24,468 acres.', '<p>Played a prominent ministerial role in advancing the long-pending Athikadavu–Avinashi scheme, which received administrative sanction in 2018 at an estimated cost of ₹1,652 crore. The project was designed to pump surplus Bhavani River water to recharge 32 PWD tanks, 42 Panchayat Union tanks and 971 ponds across Coimbatore, Tiruppur and Erode districts, benefiting approximately 24,468 acres.</p>', 'water', true, 10),
('noyyal-river-rejuvenation', 'Launching the Noyyal River Rejuvenation Project', 'A ₹230-crore project across 158.35 km of the Noyyal, from Coimbatore to Karur.', '<p>In 2020, Velumani inaugurated the ₹230-crore Noyyal River rejuvenation project covering 158.35 km across Coimbatore, Tiruppur, Erode and Karur districts. The project included work on 18 check dams, 22 ponds, damaged dams and sluice gates, strengthening of pond banks and desilting.</p>', 'river', false, 20),
('coimbatore-urban-infrastructure', 'Major Expansion of Coimbatore’s Urban Infrastructure', 'Roads, flyovers, bridges and water-supply projects across Coimbatore.', '<p>During the AIADMK government, Coimbatore saw a major programme of road expansion, flyovers, bridges, water-supply projects and other civic infrastructure, with Velumani serving as Municipal Administration Minister and as a prominent political representative of the region. Contemporary reporting records his role in launching and advocating several of these projects.</p>', 'city', false, 30),
('avinashi-road-elevated-corridor', 'Avinashi Road Elevated Corridor', 'Construction of the 10.1-km, ₹1,621.30-crore corridor from Uppilipalayam to Goldwins began in 2020.', '<p>Construction of the 10.1-km Avinashi Road elevated corridor between Uppilipalayam and Goldwins began in December 2020, at an estimated cost of ₹1,621.30 crore. Velumani, then Municipal Administration Minister, launched the construction.</p>', 'flyover', false, 40),
('coimbatore-smart-city-lakes', 'Coimbatore Smart City Lake-Development Programme', 'Rejuvenation of Ukkadam Big Tank, Valankulam and Selva Chinthamani Lake with promenades and public spaces.', '<p>The Smart City programme took up major development and rejuvenation works around Coimbatore’s lakes, including Ukkadam Big Tank, Valankulam and Selva Chinthamani Lake, with promenades, public spaces, cycle tracks and related infrastructure planned around the water bodies.</p>', 'lake', false, 50),
('ukkadam-big-tank-development', 'Development of Ukkadam Big Tank', 'A ₹39.74-crore park opened in 2020 as part of the wider lake-development programme.', '<p>A major public-space development was undertaken around Ukkadam Big Tank, including a park opened in 2020 at a reported cost of ₹39.74 crore as part of the wider lake-development programme.</p>', 'park', false, 60),
('pillur-iii-drinking-water-project', 'Pillur III Drinking-Water Project', 'A ₹165-crore third phase with a new treatment plant, taken forward during his tenure.', '<p>The third phase of the Pillur drinking-water scheme, including a new treatment plant, received a ₹165-crore project allocation and was taken forward during his tenure as Municipal Administration Minister.</p>', 'tap', false, 70),
('drinking-water-new-coimbatore-areas', 'Drinking Water for Newly Added Coimbatore Areas', 'Water supply expanded to Kavundampalayam, Vadavalli, Veerakeralam and other areas.', '<p>Water-supply infrastructure was expanded for areas including Kavundampalayam, Vadavalli and Veerakeralam as part of the broader urban expansion and municipal-infrastructure programme.</p>', 'pipe', false, 80),
('rural-roads-and-connectivity', 'Large-Scale Rural Road and Connectivity Development', 'Extensive rural roads, bridges and connectivity programmes across Tamil Nadu.', '<p>During his tenure as Rural Development Minister, Tamil Nadu’s Rural Development Department implemented extensive rural-road, bridge and connectivity programmes, forming a significant part of the state’s rural infrastructure development.</p>', 'road', false, 90),
('water-conservation-and-recharge', 'Water Conservation and Groundwater Recharge', 'Ponds, check dams, farm ponds and recharge structures, recognised nationally.', '<p>Rural-development programmes during his tenure included ponds, check dams, water-recharge structures, farm ponds and other natural-resource-management works aimed at improving water availability and groundwater recharge. The department’s programmes were also recognised nationally for water-conservation implementation.</p>', 'recharge', false, 100),
('national-recognition-mgnrega', 'National Recognition for MGNREGA Implementation', 'National awards for timely wages, Geo-MGNREGA and Aadhaar seeding.', '<p>Tamil Nadu received national recognition for its implementation of MGNREGA during his tenure, including awards relating to timely payment of wages, Geo-MGNREGA and Aadhaar seeding/conversion. Contemporary reports recorded multiple national awards presented to Velumani on behalf of the state.</p>', 'award', false, 110),
('national-rural-development-awards-2019', 'National Awards for Rural Development, 2019', 'Multiple national recognitions in the 2018–19 cycle across MGNREGA and other programmes.', '<p>In the 2018–19 national award cycle, Tamil Nadu received multiple national-level recognitions across MGNREGA and other rural-development programmes. Government policy documentation records two state-level, four district-level, one block-level and one village-panchayat-level national awards specifically under MGNREGA.</p>', 'trophy', false, 120),
('e-panchayat-puraskar', 'e-Panchayat Puraskar and Digital Panchayats', 'National award for using technology in Panchayati Raj institutions, received in 2019.', '<p>Tamil Nadu received the national e-Panchayat Puraskar for promoting the use of information and communication technology in Panchayati Raj institutions. Velumani received the award from Union Minister Narendra Singh Tomar in 2019.</p>', 'digital', true, 130),
('digital-governance-village-panchayats', 'Digital Governance Across Village Panchayats', 'Computerisation, connectivity, Aadhaar-based wages and geo-tagged assets.', '<p>Under the Rural Development Department, Tamil Nadu expanded computerisation and connectivity across village Panchayats, alongside systems such as electronic measurement records, Aadhaar-based wage payments and geo-tagging of MGNREGA assets.</p>', 'network', false, 140),
('mission-scale-mgnrega', 'Mission-Scale Implementation of MGNREGA', 'In 2018: work for 58 lakh people, 23.89 crore person-days and ₹5,344 crore in wages.', '<p>Tamil Nadu’s MGNREGA programme during this period operated at very large scale, with government records documenting extensive employment generation, wage payments and creation of durable rural assets. In 2018, contemporary reporting recorded work provided to 58 lakh people through 23.89 crore person-days, with ₹5,344 crore paid in wages.</p>', 'workers', false, 150),
('rural-public-assets-mgnrega', 'Creating Rural Public Assets', 'Anganwadis, Panchayat buildings, markets, storage, roads and more through MGNREGA.', '<p>MGNREGA implementation during his tenure supported the creation of a wide range of rural assets, including Anganwadi buildings, Panchayat buildings, rural markets, storage facilities, cattle shelters, roads, water-conservation structures and other community infrastructure.</p>', 'building', false, 160),
('rural-housing-and-sanitation', 'Expansion of Rural Housing and Sanitation', 'Large-scale construction of rural houses and sanitation infrastructure.', '<p>Rural-development programmes under the state government during this period included large-scale construction of rural houses and sanitation infrastructure, forming an important component of the state’s rural-development agenda.</p>', 'house', false, 170),
('kongu-water-resources', 'Water Resources for Coimbatore and the Kongu Region', 'Athikadavu–Avinashi, Noyyal, Pillur III and the lakes put water security at the centre.', '<p>His ministerial tenure became particularly associated with a cluster of major water-resource initiatives in and around Coimbatore — including Athikadavu–Avinashi, Noyyal rejuvenation, Pillur III and lake-rejuvenation projects — bringing water security and groundwater recharge into the centre of the region’s infrastructure agenda.</p>', 'region', false, 180),
('thondamuthur-development', 'Development Initiatives in Thondamuthur', 'Roads, the taluk office, a college and check dams for the constituency.', '<p>Development initiatives associated with his constituency include expansion of roads, construction of government infrastructure, check dams and educational institutions. In 2026, Velumani specifically cited the construction of the Thondamuthur taluk office, road expansion, a college and check dams during the AIADMK government’s tenure.</p>', 'landmark', false, 190),
('rural-development-minister-tenure', 'Seven Years as Rural Development Minister', 'Tamil Nadu’s Rural Development Minister from 20 May 2014 to 6 May 2021.', '<p>Velumani served as Tamil Nadu’s Rural Development Minister from 20 May 2014 to 6 May 2021, according to the Tamil Nadu Rural Development and Panchayat Raj Department’s official records. His tenure encompassed a period of major rural infrastructure, MGNREGA, Panchayat digitalisation, water conservation and local-government programmes.</p>', 'calendar', false, 200)
ON CONFLICT ("slug") DO NOTHING;
